import { mkdirSync, writeFileSync } from "fs";
import path from "path";
import type { Plugin } from "vite";

const MOCKUPS_DIR = "src/components/mockups";
const GENERATED_MODULE = "src/.generated/mockup-components.ts";
const GENERATED_SOURCE = [
  "// This file is generated by mockupPreviewPlugin.ts.",
  "type ModuleMap = Record<string, () => Promise<Record<string, unknown>>>;",
  'const discovered: Record<string, () => Promise<Record<string, unknown>>> = import.meta.glob<Record<string, unknown>>("../components/mockups/**/*.tsx");',
  "export const modules: ModuleMap = Object.fromEntries(",
  "  Object.entries(discovered)",
  '    .filter(([key]) => key.split("/").every((segment) => !segment.startsWith("_")))',
  '    .map(([key, loader]) => [key.startsWith("../components/") ? `./components${key.slice("../components".length)}` : key, loader]),',
  ");",
  "",
].join("\n");

export function mockupPreviewPlugin(): Plugin {
  let root = "";

  function getMockupsAbsDir(): string {
    return path.join(root, MOCKUPS_DIR);
  }

  function getGeneratedModuleAbsPath(): string {
    return path.join(root, GENERATED_MODULE);
  }

  function writeGeneratedModule(): void {
    const generatedModuleAbsPath = getGeneratedModuleAbsPath();
    mkdirSync(path.dirname(generatedModuleAbsPath), { recursive: true });
    writeFileSync(generatedModuleAbsPath, GENERATED_SOURCE);
  }

  return {
    name: "mockup-preview",
    enforce: "pre",

    configResolved(config) {
      root = config.root;
    },

    buildStart() {
      writeGeneratedModule();
    },

    configureServer() {
      mkdirSync(getMockupsAbsDir(), { recursive: true });
    },
  };
}
